package io.github.ningpp.compat;

import java.util.Arrays;
import java.util.Iterator;
import java.util.NoSuchElementException;

/**
 * Replacement for System.Buffers.ReadOnlySequence&lt;T&gt; (generated by CSharpToJava
 * converter). Single-segment array-backed implementation.
 */
public final class ReadOnlySequence<T> implements Iterable<ReadOnlyMemory<T>> {

    @SuppressWarnings("rawtypes")
    public static final ReadOnlySequence Empty = new ReadOnlySequence<>();

    private final T[] data;
    private final int start;
    private final int length;
    private int traversalIndex;

    /** Default (empty) sequence — corresponds to default(ReadOnlySequence&lt;T&gt;). */
    public ReadOnlySequence() {
        this.data = null;
        this.start = 0;
        this.length = 0;
        this.traversalIndex = 0;
    }

    public ReadOnlySequence(T[] data) {
        this(data, 0, data == null ? 0 : data.length);
    }

    /** C# ReadOnlySequence&lt;byte&gt;(byte[]) — boxes each byte as Integer. */
    @SuppressWarnings("unchecked")
    public ReadOnlySequence(byte[] data) {
        this((T[]) boxBytes(data), 0, data == null ? 0 : data.length);
    }

    private static Integer[] boxBytes(byte[] data) {
        if (data == null) {
            return null;
        }
        Integer[] boxed = new Integer[data.length];
        for (int i = 0; i < data.length; i++) {
            boxed[i] = data[i] & 0xFF;
        }
        return boxed;
    }

    public ReadOnlySequence(T[] data, int start, int length) {
        this.data = data;
        this.start = start;
        this.length = length;
        this.traversalIndex = 0;
    }

    /** Wraps a single ReadOnlyMemory as a one-segment sequence. */
    public ReadOnlySequence(ReadOnlyMemory<T> memory) {
        ReadOnlySpan<T> span = memory.getSpan();
        this.data = span.toArray();
        this.start = 0;
        this.length = span.length();
        this.traversalIndex = 0;
    }

    /**
     * Mirrors the segment-chain constructor
     * ReadOnlySequence(ReadOnlySequenceSegment&lt;T&gt;, int, ReadOnlySequenceSegment&lt;T&gt;, int) —
     * materializes the segment chain into the array-backed storage.
     */
    @SuppressWarnings("unchecked")
    public ReadOnlySequence(ReadOnlySequenceSegment<T> startSegment, int startIndex,
                            ReadOnlySequenceSegment<T> endSegment, int endIndex) {
        if (startSegment == null || endSegment == null) {
            this.data = null;
            this.start = 0;
            this.length = 0;
            this.traversalIndex = 0;
            return;
        }
        int total = 0;
        for (ReadOnlySequenceSegment<T> seg = startSegment; seg != null; seg = seg.getNext()) {
            total += seg.getMemory().getLength();
            if (seg == endSegment) {
                break;
            }
        }
        T[] merged = (T[]) new Object[total];
        int pos = 0;
        for (ReadOnlySequenceSegment<T> seg = startSegment; seg != null; seg = seg.getNext()) {
            ReadOnlySpan<T> span = seg.getMemory().getSpan();
            int segLen = span.length();
            for (int i = 0; i < segLen; i++) {
                merged[pos++] = span.get(i);
            }
            if (seg == endSegment) {
                break;
            }
        }
        this.data = merged;
        this.start = startIndex;
        int computedLength = total - startIndex - (total - endIndex > 0 ? total - endIndex : 0);
        this.length = Math.max(computedLength, 0);
        this.traversalIndex = 0;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Start — the starting position. */
    public SequencePosition getStart() {
        return new SequencePosition();
    }

    /**
     * Mirrors ReadOnlySequence&lt;T&gt;.TryGet(ref SequencePosition, out ReadOnlyMemory&lt;T&gt;, bool).
     * Single-segment implementation: the first call returns the whole sequence,
     * subsequent calls report the end. The wildcard parameter accepts both typed
     * and Object holders without an erasure clash.
     */
    public boolean tryGet(ObjectHolder<SequencePosition> nextPosition, ObjectHolder<? super ReadOnlyMemory<T>> memory, boolean advance) {
        if (traversalIndex >= 1 || length == 0) {
            memory.value = new ReadOnlyMemory<>();
            return false;
        }
        traversalIndex++;
        memory.value = getFirst();
        return true;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.GetPosition(long, SequencePosition). */
    public SequencePosition getPosition(long offset, SequencePosition position) {
        return new SequencePosition();
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.First — the first segment (this single segment). */
    public ReadOnlyMemory<T> getFirst() {
        if (length == 0) {
            return new ReadOnlyMemory<>();
        }
        @SuppressWarnings("unchecked")
        T[] copy = (T[]) Arrays.copyOfRange(data, start, start + length);
        return new ReadOnlyMemory<>(copy);
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Length. */
    public long getLength() {
        return length;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.IsSingleSegment. */
    public boolean getIsSingleSegment() {
        return true;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.IsEmpty. */
    public boolean getIsEmpty() {
        return length == 0;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(long). */
    public ReadOnlySequence<T> slice(long sliceStart) {
        return slice(sliceStart, length - sliceStart);
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(long, long). */
    public ReadOnlySequence<T> slice(long sliceStart, long sliceLength) {
        if (sliceStart < 0 || sliceLength < 0 || sliceStart + sliceLength > length) {
            throw new IndexOutOfBoundsException(
                "start=" + sliceStart + ", length=" + sliceLength + ", sequenceLength=" + length);
        }
        if (sliceLength == 0) {
            return new ReadOnlySequence<>();
        }
        return new ReadOnlySequence<>(data, start + (int) sliceStart, (int) sliceLength);
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(SequencePosition, SequencePosition) — single-segment pass-through. */
    public ReadOnlySequence<T> slice(SequencePosition start, SequencePosition end) {
        return this;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(SequencePosition) — single-segment pass-through. */
    public ReadOnlySequence<T> slice(SequencePosition start) {
        if (start == null || start.getInteger() == 0) {
            return this;
        }
        return slice(start.getInteger());
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(int, SequencePosition) — single-segment pass-through. */
    public ReadOnlySequence<T> slice(int start, SequencePosition end) {
        if (end == null || end.getInteger() == 0) {
            return this;
        }
        return slice(start);
    }

    /** Iterates the single segment — mirrors C# foreach over a ReadOnlySequence. */
    @Override
    public Iterator<ReadOnlyMemory<T>> iterator() {
        return new Iterator<>() {
            private boolean consumed = false;

            @Override
            public boolean hasNext() {
                return !consumed && length > 0;
            }

            @Override
            public ReadOnlyMemory<T> next() {
                if (!hasNext()) throw new NoSuchElementException();
                consumed = true;
                return getFirst();
            }
        };
    }
}
